import React, { useState, useEffect, useMemo } from 'react';
import { MarketInsight, Category, CompletionStatus, SortMode } from './types';
import { CATEGORIES, INITIAL_INSIGHTS } from './constants';
import MarketCard from './components/MarketCard';
import InsightForm from './components/InsightForm';
import { Plus, LayoutGrid, ListFilter, CalendarDays, Archive, Sparkles, X, ChevronDown } from 'lucide-react';
import { generateMarketSummary } from './services/geminiService';

const App: React.FC = () => {
  const [insights, setInsights] = useState<MarketInsight[]>(() => {
    const saved = localStorage.getItem('trading_journal_v3');
    return saved ? JSON.parse(saved) : INITIAL_INSIGHTS;
  });

  const [activeCategory, setActiveCategory] = useState<Category>('全部');
  const [selectedMonth, setSelectedMonth] = useState<string | null>(null);
  const [sortMode, setSortMode] = useState<SortMode>('category');
  const [showForm, setShowForm] = useState(false);
  const [editingInsight, setEditingInsight] = useState<MarketInsight | undefined>(undefined);
  const [isGeneratingAI, setIsGeneratingAI] = useState(false);
  const [aiSummary, setAiSummary] = useState('');
  const [showAiReport, setShowAiReport] = useState(false);

  useEffect(() => {
    localStorage.setItem('trading_journal_v3', JSON.stringify(insights));
  }, [insights]);

  const timelineGroups = useMemo(() => {
    const groups: { [key: string]: number } = {};
    insights.forEach(i => {
      const date = new Date(i.updatedAt);
      const key = `${date.getFullYear()}年${date.getMonth() + 1}月`;
      groups[key] = (groups[key] || 0) + 1;
    });
    return Object.entries(groups).sort((a, b) => b[0].localeCompare(a[0]));
  }, [insights]);

  const filteredInsights = useMemo(() => {
    let result = insights;
    if (activeCategory !== '全部') {
      result = result.filter(i => i.category === activeCategory);
    }
    if (selectedMonth) {
      result = result.filter(i => {
        const date = new Date(i.updatedAt);
        return `${date.getFullYear()}年${date.getMonth() + 1}月` === selectedMonth;
      });
    }
    return result;
  }, [insights, activeCategory, selectedMonth]);

  const { activeItems, archivedItems } = useMemo(() => {
    return {
      activeItems: filteredInsights.filter(i => i.completionStatus === '进行中'),
      archivedItems: filteredInsights.filter(i => i.completionStatus !== '进行中')
    };
  }, [filteredInsights]);

  const groupedActiveInsights = useMemo(() => {
    const groups: { [label: string]: MarketInsight[] } = {};
    activeItems.forEach(insight => {
      let label = sortMode === 'timeline' 
        ? new Date(insight.updatedAt).toLocaleDateString('zh-CN', { year: 'numeric', month: 'long', day: 'numeric' })
        : insight.category;
      if (!groups[label]) groups[label] = [];
      groups[label].push(insight);
    });
    const entries = Object.entries(groups);
    return sortMode === 'category' 
      ? entries.sort((a, b) => CATEGORIES.indexOf(a[0] as any) - CATEGORIES.indexOf(b[0] as any))
      : entries.sort((a, b) => b[1][0].updatedAt - a[1][0].updatedAt);
  }, [activeItems, sortMode]);

  const handleSaveInsight = (data: Partial<MarketInsight>) => {
    if (editingInsight) {
      setInsights(prev => prev.map(i => i.id === editingInsight.id ? { ...i, ...data, updatedAt: data.updatedAt || i.updatedAt } as MarketInsight : i));
    } else {
      const newInsight: MarketInsight = {
        id: Math.random().toString(36).substr(2, 9),
        ...data as any,
        updatedAt: data.updatedAt || Date.now(),
        completionStatus: data.completionStatus || '进行中',
      };
      setInsights(prev => [newInsight, ...prev]);
    }
    setShowForm(false);
    setEditingInsight(undefined);
  };

  const handleDeleteInsight = (id: string) => {
    if (window.confirm('确定要删除这条市场记录吗？')) {
      setInsights(prev => prev.filter(i => i.id !== id));
    }
  };

  const handleToggleStatus = (id: string) => {
    const statuses: CompletionStatus[] = ['进行中', '已完成', '已失效'];
    setInsights(prev => prev.map(i => {
      if (i.id === id) {
        const currentIndex = statuses.indexOf(i.completionStatus);
        return { ...i, completionStatus: statuses[(currentIndex + 1) % statuses.length] };
      }
      return i;
    }));
  };

  const handleGenerateAI = async () => {
    if (insights.length === 0) return;
    setIsGeneratingAI(true);
    const summary = await generateMarketSummary(insights);
    setAiSummary(summary || "分析完成。");
    setIsGeneratingAI(false);
    setShowAiReport(true);
  };

  return (
    <div className="min-h-screen flex flex-col selection:bg-amber-100">
      {/* 极简顶栏 */}
      <header className="sticky top-0 z-[100] bg-white/80 backdrop-blur-xl border-b border-gray-100 px-8 h-[72px]">
        <div className="max-w-[1600px] mx-auto flex items-center justify-between h-full">
          <div className="flex items-center gap-3">
            <div className="bg-[#12141c] w-8 h-8 rounded-lg flex items-center justify-center">
              <LayoutGrid className="w-4 h-4 text-white" />
            </div>
            <h1 className="text-lg font-black text-[#12141c] tracking-tighter">市场周刊</h1>
          </div>

          <nav className="hidden md:flex items-center gap-1 bg-gray-100/50 p-1 rounded-2xl">
            {CATEGORIES.map(cat => (
              <button
                key={cat}
                onClick={() => setActiveCategory(cat)}
                className={`px-5 py-2 rounded-xl text-[13px] font-bold transition-all ${
                  activeCategory === cat 
                    ? 'bg-white text-gray-900 shadow-sm' 
                    : 'text-gray-400 hover:text-gray-900'
                }`}
              >
                {cat}
              </button>
            ))}
          </nav>

          <div className="flex items-center gap-4">
            {/* 还原截图中的 AI 按钮 */}
            <button 
              onClick={handleGenerateAI}
              disabled={isGeneratingAI || insights.length === 0}
              className={`flex items-center gap-2.5 px-6 py-3 bg-[#12141c] text-white rounded-full ai-glow transition-all active:scale-95 disabled:opacity-50 group ${isGeneratingAI ? 'cursor-wait' : 'cursor-pointer'}`}
            >
              <Sparkles className={`w-4 h-4 text-amber-400 fill-amber-400 ${isGeneratingAI ? 'animate-spin' : ''}`} />
              <span className="text-[14px] font-bold tracking-tight">
                {isGeneratingAI ? '智能分析中...' : '获取 AI 智能周报'}
              </span>
            </button>

            <button 
              onClick={() => { setEditingInsight(undefined); setShowForm(true); }}
              className="bg-[#12141c] text-white w-10 h-10 rounded-full flex items-center justify-center hover:scale-105 transition-all shadow-lg active:scale-90"
            >
              <Plus className="w-5 h-5" />
            </button>
          </div>
        </div>
      </header>

      <div className="max-w-[1600px] mx-auto px-8 py-12 w-full flex flex-col lg:flex-row gap-16">
        {/* 极简侧边栏 */}
        <aside className="lg:w-48 space-y-10 flex-shrink-0">
          <div className="sticky top-[100px]">
            <h3 className="text-[11px] font-black text-gray-300 uppercase tracking-[0.2em] mb-6">Archive</h3>
            <div className="space-y-1">
              <button
                onClick={() => setSelectedMonth(null)}
                className={`w-full text-left px-4 py-3 rounded-xl text-[13px] font-bold transition-all flex items-center justify-between ${
                  selectedMonth === null ? 'bg-[#12141c] text-white' : 'text-gray-400 hover:bg-gray-100'
                }`}
              >
                <span>全部</span>
                <span className="text-[10px] opacity-50">{insights.length}</span>
              </button>
              {timelineGroups.map(([month, count]) => (
                <button
                  key={month}
                  onClick={() => setSelectedMonth(month)}
                  className={`w-full text-left px-4 py-3 rounded-xl text-[13px] font-bold transition-all flex items-center justify-between ${
                    selectedMonth === month ? 'bg-[#12141c] text-white' : 'text-gray-400 hover:bg-gray-100'
                  }`}
                >
                  <span>{month}</span>
                  <span className="text-[10px] opacity-50">{count}</span>
                </button>
              ))}
            </div>
          </div>
        </aside>

        <main className="flex-grow">
          {/* AI 报表区 */}
          {aiSummary && showAiReport && (
            <div className="mb-16 animate-in slide-in-from-top-4 duration-500">
              <div className="bg-[#12141c] rounded-[2.5rem] p-12 text-white relative overflow-hidden shadow-2xl">
                <div className="absolute top-0 right-0 w-80 h-80 bg-amber-400/10 blur-[100px] -mr-40 -mt-40 rounded-full" />
                <div className="relative z-10">
                  <div className="flex justify-between items-start mb-10">
                    <div className="flex items-center gap-3">
                      <div className="p-2 bg-amber-400/10 rounded-xl">
                        <Sparkles className="w-5 h-5 text-amber-400 fill-amber-400" />
                      </div>
                      <h2 className="text-xl font-black">AI 智能研判周报</h2>
                    </div>
                    <button onClick={() => setShowAiReport(false)} className="p-2 hover:bg-white/10 rounded-full transition-colors">
                      <X className="w-5 h-5 text-gray-400" />
                    </button>
                  </div>
                  <div className="text-lg md:text-xl font-medium leading-[1.8] text-gray-200 whitespace-pre-wrap">
                    {aiSummary}
                  </div>
                </div>
              </div>
            </div>
          )}

          {!showAiReport && aiSummary && (
             <button 
              onClick={() => setShowAiReport(true)}
              className="mb-12 w-full py-4 border border-dashed border-gray-200 rounded-2xl text-[13px] font-bold text-gray-400 hover:border-[#12141c] hover:text-[#12141c] transition-all flex items-center justify-center gap-2"
             >
                <ChevronDown className="w-4 h-4" />
                查看最近一次 AI 智能研判
             </button>
          )}

          <div className="flex flex-col md:flex-row md:items-end justify-between gap-8 mb-16">
            <h2 className="text-5xl font-black text-[#12141c] tracking-tighter leading-tight italic">
              追踪市场，<br />记录每一次智慧。
            </h2>
            <div className="flex bg-gray-100 p-1 rounded-xl border border-gray-200">
              <button onClick={() => setSortMode('category')} className={`px-5 py-2 rounded-lg text-[12px] font-black transition-all ${sortMode === 'category' ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-400'}`}>
                <ListFilter className="w-3.5 h-3.5 mr-1 inline" /> 类别
              </button>
              <button onClick={() => setSortMode('timeline')} className={`px-5 py-2 rounded-lg text-[12px] font-black transition-all ${sortMode === 'timeline' ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-400'}`}>
                <CalendarDays className="w-3.5 h-3.5 mr-1 inline" /> 时间
              </button>
            </div>
          </div>

          {activeItems.length > 0 ? (
            <div className="space-y-16">
              {groupedActiveInsights.map(([groupLabel, groupItems]) => (
                <section key={groupLabel}>
                  <div className="flex items-center gap-4 mb-10">
                    <span className="text-[12px] font-black tracking-widest uppercase bg-[#12141c] text-white px-4 py-1.5 rounded-full">{groupLabel}</span>
                    <div className="flex-grow h-[1px] bg-gray-100" />
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8">
                    {groupItems.map(insight => (
                      <MarketCard 
                        key={insight.id} 
                        insight={insight} 
                        onEdit={(i) => { setEditingInsight(i); setShowForm(true); }}
                        onDelete={handleDeleteInsight}
                        onToggleStatus={handleToggleStatus}
                      />
                    ))}
                  </div>
                </section>
              ))}
            </div>
          ) : (
            <div className="text-center py-32 border-2 border-dashed border-gray-100 rounded-[3rem]">
              <Plus className="w-10 h-10 text-gray-200 mx-auto mb-4" />
              <h3 className="text-xl font-black text-gray-900">暂无进行中的记录</h3>
              <p className="text-sm text-gray-400 mt-1">点击右上角添加您的市场观察</p>
            </div>
          )}

          {archivedItems.length > 0 && (
            <div className="mt-40 pt-20 border-t border-gray-100">
               <div className="flex items-center gap-4 mb-12 opacity-30">
                  <Archive className="w-6 h-6 text-[#12141c]" />
                  <h3 className="text-xl font-black text-[#12141c]">历史归档</h3>
               </div>
              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8 grayscale">
                {archivedItems.map(insight => (
                  <MarketCard 
                    key={insight.id} 
                    insight={insight} 
                    onEdit={(i) => { setEditingInsight(i); setShowForm(true); }}
                    onDelete={handleDeleteInsight}
                    onToggleStatus={handleToggleStatus}
                  />
                ))}
              </div>
            </div>
          )}
        </main>
      </div>

      <footer className="mt-auto py-16 border-t border-gray-100 text-center">
          <p className="text-[11px] text-gray-300 font-black uppercase tracking-[0.5em]">Trading Journal · YouMind Inspired</p>
      </footer>

      {showForm && (
        <InsightForm 
          initialData={editingInsight}
          onSave={handleSaveInsight}
          onCancel={() => { setShowForm(false); setEditingInsight(undefined); }}
        />
      )}
    </div>
  );
};

export default App;

import React from 'react';
import { MarketInsight, AssetStatus } from '../types';
import { Edit2, Trash2, Calendar, TrendingUp, TrendingDown, Activity, Target, ChevronRight } from 'lucide-react';

interface MarketCardProps {
  insight: MarketInsight;
  onEdit: (insight: MarketInsight) => void;
  onDelete: (id: string) => void;
  onToggleStatus?: (id: string) => void;
}

const getAssetStatusStyle = (status: AssetStatus) => {
  switch (status) {
    case '看涨': return {
      color: 'text-red-500',
      bg: 'bg-red-50',
      border: 'border-red-100',
      icon: <TrendingUp className="w-4 h-4" />
    };
    case '看跌': return {
      color: 'text-emerald-500',
      bg: 'bg-emerald-50',
      border: 'border-emerald-100',
      icon: <TrendingDown className="w-4 h-4" />
    };
    default: return {
      color: 'text-blue-500',
      bg: 'bg-blue-50',
      border: 'border-blue-100',
      icon: <Activity className="w-4 h-4" />
    };
  }
};

const MarketCard: React.FC<MarketCardProps> = ({ insight, onEdit, onDelete, onToggleStatus }) => {
  const date = new Date(insight.updatedAt).toLocaleDateString('zh-CN', {
    month: 'short',
    day: 'numeric'
  });

  const { color, bg, border, icon } = getAssetStatusStyle(insight.status);
  const isArchived = insight.completionStatus !== '进行中';

  return (
    <div className={`group relative bg-white border border-gray-100 rounded-[2.5rem] p-8 transition-all duration-500 hover:shadow-[0_30px_60px_-15px_rgba(0,0,0,0.08)] flex flex-col min-h-[400px] ${isArchived ? 'opacity-60 hover:opacity-100' : ''}`}>

      {/* 顶部标识 */}
      <div className="flex justify-between items-start mb-8">
        <div>
          <h3 className="text-3xl font-black text-[#12141c] tracking-tighter mb-1">{insight.symbol}</h3>
          <div className="flex items-center text-[12px] text-gray-400 font-bold gap-2">
            <Calendar className="w-3.5 h-3.5" />
            {date}
          </div>
        </div>
        <button 
          onClick={() => onToggleStatus?.(insight.id)}
          className={`px-4 py-1.5 rounded-full text-[11px] font-black border uppercase tracking-wider transition-all ${bg} ${color} ${border}`}
        >
          {insight.status}
        </button>
      </div>

      {/* 内容主体 */}
      <div className="flex-grow space-y-6">
        <div>
          <p className="text-[11px] font-black text-gray-300 uppercase tracking-widest mb-2">Insight</p>
          <p className="text-[15px] font-medium leading-relaxed text-gray-700">
            {insight.focusPoints}
          </p>
        </div>

        {insight.entryLevel && (
          <div className="flex items-center gap-3 text-gray-900">
            <Target className="w-4 h-4 text-gray-400" />
            <span className="text-[14px] font-black">Entry: {insight.entryLevel}</span>
          </div>
        )}

        <div className="pt-4 border-t border-gray-50">
          <p className="text-[11px] font-black text-gray-300 uppercase tracking-widest mb-2">Strategy</p>
          <div className="flex items-start gap-3">
             <ChevronRight className={`w-4 h-4 mt-0.5 ${color}`} />
             <p className="text-[15px] font-bold text-[#12141c] leading-snug">
               {insight.strategy}
             </p>
          </div>
        </div>
      </div>

      {/* 底部工具 */}
      <div className="mt-8 pt-6 border-t border-gray-50 flex justify-between items-center opacity-0 group-hover:opacity-100 transition-all duration-300">
        <span className="text-[10px] font-black text-gray-300 uppercase tracking-widest">{insight.category}</span>
        <div className="flex gap-1">
          <button 
            onClick={() => onEdit(insight)}
            className="p-2.5 text-gray-400 hover:text-[#12141c] hover:bg-gray-100 rounded-xl transition-all"
          >
            <Edit2 className="w-4 h-4" />
          </button>
          <button 
            onClick={() => onDelete(insight.id)}
            className="p-2.5 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all"
          >
            <Trash2 className="w-4 h-4" />
          </button>
        </div>
      </div>
    </div>
  );
};

export default MarketCard;

import { GoogleGenAI } from "@google/genai";
import { MarketInsight } from "../types";

export const generateMarketSummary = async (insights: MarketInsight[]) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    你是一个资深的市场战略分析师，供职于一家顶级对冲基金。
    请根据以下市场观察数据，为我生成一份本周的“深度研判周报”。

    要求：
    1. 风格：极其简洁、专业、透彻。
    2. 结构：
       - 【市场共识】：目前多空力量对比的宏观感受。
       - 【关键博弈】：挑选1-2个最重要的资产，分析其核心逻辑。
       - 【风控建议】：针对目前仓位和潜在风险的最高频建议。
    3. 字数控制：300字以内，使用极简的排版。

    待分析数据：
    ${insights.map(i => `- ${i.symbol} (${i.status}): ${i.focusPoints}. 策略: ${i.strategy}`).join('\n')}
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("AI Summary Error:", error);
    return "暂时无法生成 AI 研判，请检查 API 配置或稍后再试。";
  }
};
